import{_ as t,o,c as d,ag as a}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Student Dashboard -> Profile Setting (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/profile-setting.md","filePath":"modules/student-dashboard/profile-setting.md"}'),r={name:"modules/student-dashboard/profile-setting.md"};function s(i,e,l,n,u,c){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="student-dashboard-profile-setting-deep" tabindex="-1">Student Dashboard -&gt; Profile Setting (deep) <a class="header-anchor" href="#student-dashboard-profile-setting-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Profile Setting (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>profile-setting</code><br><strong>Routes:</strong> <code>/student-dashboard/settings</code>, <code>/student-dashboard/settings/edit-profile</code></p><p>This feature covers the student’s personal profile view/edit flow and the lesson-history/profile presentation embedded in the settings area.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show the student’s saved profile information in a dashboard-friendly view.</li><li>Allow profile editing, image upload, address entry, and language preference selection.</li><li>Surface lesson-history/profile context in the same settings area.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/student-dashboard/profileSetting.tsx</code></td><td>Main profile settings page</td><td>Loads student profile, renders profile summary, and hosts nested edit route via <code>Outlet</code>.</td></tr><tr><td><code>Frontend/src/pages/private/student-dashboard/EditStudentProfile.tsx</code></td><td>Edit profile form</td><td>Sends profile updates, image upload flow, address lookup, and validation UX.</td></tr><tr><td><code>Frontend/src/pages/private/student-dashboard/StudentBookings.tsx</code></td><td>Related lesson-history surface</td><td>Used from settings/profile flows to show booking history context.</td></tr><tr><td><code>Frontend/src/hooks/useFileUpload.ts</code></td><td>Upload helper</td><td>Handles upload URL + file upload flow for profile image/documents.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/common/BackButton.tsx</code></td><td>Shared back-navigation UI</td><td>Used in nested edit flow.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="student-profile-queries-mutations" tabindex="-1">Student profile queries/mutations <a class="header-anchor" href="#student-profile-queries-mutations" aria-label="Permalink to &quot;Student profile queries/mutations&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/studentProfile.ts</code></li><li>Relevant operations: <ul><li><code>GET_STUDENT_PROFILE</code></li><li><code>UPDATE_STUDENT_PROFILE</code></li></ul></li><li>Used by: <ul><li><code>profileSetting.tsx</code></li><li><code>EditStudentProfile.tsx</code></li></ul></li></ul><h3 id="shared-upload-profile-helpers" tabindex="-1">Shared upload/profile helpers <a class="header-anchor" href="#shared-upload-profile-helpers" aria-label="Permalink to &quot;Shared upload/profile helpers&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/profile.ts</code></li><li>Used for upload URL generation and shared profile-related helpers where applicable.</li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs.js</code><ul><li>Contains <code>studentProfile</code>, <code>setupStudentProfile</code>, <code>updateStudentProfile</code>, and shared user/profile shapes.</li></ul></li><li>File: <code>server/src/graphql/typeDefs/student.typeDefs.js</code><ul><li>Adds student-specific shapes used in profile and progress surfaces.</li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers.js</code><ul><li><code>Query.studentProfile</code></li><li><code>Mutation.setupStudentProfile</code></li><li><code>Mutation.updateStudentProfile</code></li></ul></li><li>File: <code>server/src/graphql/resolvers/student.resolver.js</code><ul><li>Student-centric read helpers that settings/history surfaces may reuse.</li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User.js</code></td><td>Student profile persistence</td></tr><tr><td><code>server/src/schemas/validation.js</code></td><td>Validation for profile setup/update inputs</td></tr><tr><td><code>server/src/config/awsConfig.js</code></td><td>Upload/storage configuration used by image/document flows</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/settings</code>.</li><li><code>GET_STUDENT_PROFILE</code> loads the current student record.</li><li>The page renders profile summary information and nested-route controls.</li><li>Student navigates to <code>/student-dashboard/settings/edit-profile</code>.</li><li>Edit page updates local form state, optionally uploads an image, and sends <code>UPDATE_STUDENT_PROFILE</code>.</li><li>On success, the student profile query is refetched and the settings page reflects the updated data.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>Address entry uses external suggestion services from the frontend; the backend ultimately stores normalized profile fields on <code>User.Student</code>.</li><li>Student payment-method state exists in the model, but this settings module does not expose full saved-card management as a standalone settings feature.</li><li>Booking history shown from the settings area overlaps conceptually with the booked-lessons feature; use this doc for profile/edit wiring, not for payment/booking-state business rules.</li></ul>',23)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
